			FoodIsNotReservedForPrisoners_SettingsCategory = "Food Is Not Reserved For Prisoners"
			FoodIsNotReservedForPrisoners_UseDefaultQ = "Usa Per Defecte?"
		} <# END Keyed/FoodIsNotReservedForPrisoners #>
