			FoodIsNotReservedForPrisoners_AllowAutomaticHaulingDescription = "Όταν ενεργοποιηθεί, αυτό θα επιτρέψει στα πιόνια να μεταφέρουν αυτόματα τρόφιμα που είναι αποθηκευμένα σε μια φυλακή.`r`nΤα τρόφιμα που ρίχνονται σε μια φυλακή από έναν φύλακα, μέσω της εργασίας παράδοσης τροφίμων, θα προορίζονται προσωρινά για κρατούμενους."
			FoodIsNotReservedForPrisoners_AllowAutomaticHaulingQ = "Να επιτρέπεται η αυτόματη ανάσυρση;"
			FoodIsNotReservedForPrisoners_CeaseReservationForPrisonersDescription = "Αυτό θα ακυρώσει την κράτηση για κρατούμενους για αυτό το πράγμα, επιτρέποντας στα πιόνια να το μεταφέρουν αυτόματα."
			FoodIsNotReservedForPrisoners_CeaseReservationForPrisonersLabel = "Παύση κράτησης για κρατούμενους"
			FoodIsNotReservedForPrisoners_DurationOfReservationForPrisonersForDroppedFood = "Διάρκεια κράτησης για κρατούμενους για φαγητό που έπεσε σε φυλακή."
			FoodIsNotReservedForPrisoners_DurationOfReservationForPrisonersForDroppedFoodDescription = "Εάν επιτρέπεται η αυτόματη μεταφορά, αυτό ελέγχει πόσο καιρό τα τρόφιμα που πέφτουν στις φυλακές θα προορίζονται για κρατούμενους."
			FoodIsNotReservedForPrisoners_ManuallyDroppedFoodIsTemporarilyReservedForPrisonersDescription = "Όταν είναι ενεργοποιημένη, και αν επιτρέπεται η αυτόματη μεταφορά, τα τρόφιμα που πέφτουν χειροκίνητα από το απόθεμα ενός πιόνου θα είναι προσωρινά διατηρημένα για κρατούμενους, όπως και για τα τρόφιμα που πέφτουν σε μια φυλακή από έναν φύλακα."
			FoodIsNotReservedForPrisoners_ManuallyDroppedFoodIsTemporarilyReservedForPrisonersQ = "Το φαγητό που πέφτει με το χέρι προορίζεται προσωρινά για κρατούμενους;"
			FoodIsNotReservedForPrisoners_Option = "Επιλογή"
			FoodIsNotReservedForPrisoners_ReservedForPrisonersForPeriod = "Κρατούμενος για φυλακισμένους για {0}."
			FoodIsNotReservedForPrisoners_Setting = "Ρυθμίσεων"
			<# Το Φαγητό Δεν Προορίζεται Για Κρατούμενους #>
			FoodIsNotReservedForPrisoners_SettingsCategory = "Food Is Not Reserved For Prisoners"
			FoodIsNotReservedForPrisoners_UseDefaultQ = "Χρησιμοποιήστε Προεπιλογή;"
		} <# END Keyed/FoodIsNotReservedForPrisoners #>
	}

	Hungarian = [Ordered] @{
